<?php
declare(strict_types=1);
putenv('RUMOHUB_ENABLED=0');putenv('RUMOHUB_BENEFITS=0');putenv('RUMO10_WORLD_CALENDAR=1');putenv('RUMO10_WORLD_FIXTURES=1');require dirname(__DIR__).'/app/bootstrap.php';
$checks=0;function check(bool $v,string $why):void{global $checks;$checks++;if(!$v)throw new RuntimeException($why);}
$g=NationalTrial::createABCDWithNordeste(820001);$steps=0;$max=0.;$peakBytes=0;$start=hrtime(true);$batchSeen=false;
while($g['stage']!=='resumo'){
 if(++$steps>4000)throw new RuntimeException('Loop');$action='choice';$input=['option'=>0];
 if(in_array($g['stage'],['world_processing','competicao_resumo'],true)){$action='continue';$input=[];if($g['stage']==='world_processing')$batchSeen=true;}
 elseif($g['stage']==='partida'){$m=$g['matches'][Game::currentIndex($g)];if($m['status']!=='em_andamento'||$m['minute']<$m['entry']||$m['minute']>=$m['exit']){$action='advance';$input=[];}}
 $before=hrtime(true);$g=Game::command($g,$action,$input);$max=max($max,(hrtime(true)-$before)/1e6);$wire=json_encode($g,JSON_THROW_ON_ERROR);$peakBytes=max($peakBytes,strlen($wire));$g=json_decode($wire,true,512,JSON_THROW_ON_ERROR);
