check($batchSeen,'processamento incremental exercitado');check(count($g['world_completed'])===8,'estadual e nacional finalizados');$b=$g['competitions']['br-b'];check(count($b['matches'])===384,'380 jogos mais quatro de playoffs');check(count($b['promoted'])===4&&count($b['relegated'])===4,'mérito de acesso e descenso');check($b['champion']===$b['initial_ranking'][0],'título por pontos corridos');check(!array_filter($b['matches'],fn($m)=>$m['phase']==='playoff'&&isset($m['penalties'])),'sem pênaltis nos playoffs B');
check(count($g['competition_results'])===4,'CRB disputou A estadual, copa e B nacional');foreach($g['external_qualifications'] as $row)check($row['state']==='pending'&&$row['consumed_entry']===null,'qualificação não é inscrição');
WorldSeason::scope($g,function()use($g,$b){$winner=$g;$winner['club']=$b['champion'];$winner['competition_results']=['br-b'=>Competition::result($b,$b['champion'])];$winner['competition_history']=[];$winner['history']=[];$titles=Trophies::collect($winner);check(count($titles)===1&&$titles[0]['competition']==='br-b','título nacional nasce dos resultados finalizados');});
$seen=[];foreach($g['world_agenda'] as $e)foreach(['home','away'] as $side){$day=strtotime($e['date'].' UTC');check(!isset($seen[$e[$side]])||$day-$seen[$e[$side]]>=3*86400,'sem conflito de descanso');$seen[$e[$side]]=$day;}
check(count($g['competitions']['br-a']['matches'])===380,'380 jogos A');check(count($g['competitions']['br-c']['matches'])===216,'216 jogos C');$closed=$g['national_pyramid_closures']['1'];check($closed['state']==='blocked'&&!$closed['memberships_applied'],'renovação bloqueada, sem movimento fantasma');check(count($closed['draft_memberships']['br-a'])===20&&count($closed['draft_memberships']['br-b'])===20&&count($closed['draft_memberships']['br-c'])===24,'trocas recíprocas e déficit real de seis clubes da D');foreach(['br-a','br-b','br-c'] as $id)check($g['next_memberships'][$id]===$g['memberships'][$id],'participantes atuais preservados até renovação possível');
check(count($g['competitions']['br-d']['matches'])===610,'D completa');check(count($g['competitions']['br-nordeste']['matches'])===60,'Nordeste completa');check(count($g['competitions']['br-d']['promoted'])===6,'seis acessos D');$coverage=MandatoryTournamentCoverage::audit($g);check($coverage['clubs']['CRB-AL']['br-nordeste']['completed'],'Nordeste obrigatória concluída');check($coverage['clubs']['CRB-AL']['br-copa']['required_uncovered'],'Copa do Brasil ausente mantém bloqueio');file_put_contents(dirname(__DIR__).'/Docs/mundializacao-v07/serie-d-renovacao-copas/mandatory-coverage.json',json_encode($coverage,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
$ledger=$g['reward_ledger'];$replay=WorldSeason::scope($g,function()use($g){WorldSeason::next($g);return $g;});check($replay['national_pyramid_closures']===$g['national_pyramid_closures'],'homologação imutável em replay');check($replay['reward_ledger']===$ledger&&$replay['external_qualifications']===$g['external_qualifications'],'replay não duplica XP nem classificações');
try{Game::command($g,'offers');throw new RuntimeException('continuação indevida');}catch(InvalidArgumentException $e){check(true,'janela bloqueada claramente até próxima edição íntegra');}
file_put_contents(dirname(__DIR__).'/Docs/mundializacao-v07/serie-d-renovacao-copas/runtime-with-nordeste.json',json_encode(['checks'=>$checks,'national_competitions'=>['br-a','br-b','br-c','br-d','br-nordeste'],'seasons'=>1,'renewals'=>0,'closure'=>$g['national_pyramid_closures']['1'],'complete_career_released'=>false,'steps'=>$steps,'batches'=>$g['world_processing_batches']??0,'max_command_ms'=>round($max,2),'elapsed_ms'=>round((hrtime(true)-$start)/1e6,2),'fixtures'=>count($g['world_agenda']),'snapshot_bytes'=>strlen(json_encode($g)),'peak_snapshot_bytes'=>$peakBytes,'player_summary'=>Game::summary($g),'national_champion'=>$b['champion']],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));echo "OK: $checks verificações estadual+nacional; edição completa, renovação bloqueada.\n";
